<section class="admin-v2-page-intro"><div><span class="admin-v2-eyebrow">PUBLIC CONTENT</span><h2>إدارة الصفحات</h2><p>تحرير الصفحات الموجودة وتغيير حالة النشر مع الحفاظ على روابطها وترجماتها.</p></div></section>
<section class="admin-v2-panel"><form method="post" action="/admin-v2/pages/save" class="admin-v2-actions"><input type="hidden" name="_token" value="<?=e(App\Core\Csrf::token())?>"><div class="admin-v2-grid-2"><label>الصفحة الحالية<select name="id"><option value="0">صفحة جديدة</option><?php foreach($pages as $page): if($page['deleted_at']===null):?><option value="<?=e($page['id'])?>"><?=e($page['title']?:'بدون عنوان')?> — #<?=e($page['id'])?></option><?php endif;endforeach;?></select></label><label>اللغة<select name="locale"><option value="ar">العربية</option><option value="en">English</option><option value="es">Español</option><option value="fr">Français</option><option value="ru">Русский</option></select></label></div><label>العنوان<input name="title" required maxlength="255"></label><label>Slug<input name="slug" required maxlength="220" dir="ltr"></label><label>المحتوى<textarea name="content" rows="7"></textarea></label><label>الحالة<select name="status"><option value="draft">مسودة</option><option value="published">منشورة</option></select></label><button class="admin-v2-button primary" type="submit">حفظ الصفحة</button></form></section>
<section class="admin-v2-table-panel"><div class="admin-v2-panel-head"><h3>الصفحات الحالية</h3><span><?=e(count($pages))?></span></div><div class="admin-v2-responsive-table"><table class="admin-v2-table"><thead><tr><th>العنوان</th><th>الرابط</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody><?php foreach($pages as $page):?><tr><td><strong><?=e($page['title']?:'بدون عنوان')?></strong><small>#<?=e($page['id'])?></small></td><td dir="ltr"><?=e($page['slug']?:'—')?></td><td><?=e($page['deleted_at']?'في السلة':$page['status'])?></td><td class="admin-v2-inline-actions"><form method="post" action="/admin-v2/pages/status"><input type="hidden" name="_token" value="<?=e(App\Core\Csrf::token())?>"><input type="hidden" name="id" value="<?=e($page['id'])?>"><input type="hidden" name="action" value="<?=$page['deleted_at']?'restore':'toggle'?>"><button class="admin-v2-button" type="submit"><?=$page['deleted_at']?'استعادة':($page['status']==='published'?'إلغاء النشر':'نشر')?></button></form><?php if(!$page['deleted_at']):?><form method="post" action="/admin-v2/pages/status"><input type="hidden" name="_token" value="<?=e(App\Core\Csrf::token())?>"><input type="hidden" name="id" value="<?=e($page['id'])?>"><input type="hidden" name="action" value="trash"><button class="admin-v2-button" type="submit">نقل للسلة</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
